import{_ as d,o as t,c as a,a3 as o}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"标准库总览","description":"","frontmatter":{"title":"标准库总览","outline":[2,3],"article":{"type":"index","structure":"index"}},"headers":[],"relativePath":"frontend/guide/core/javascript/standard-library.md","filePath":"frontend/guide/core/javascript/standard-library.md","lastUpdated":1785217527000}'),r={name:"frontend/guide/core/javascript/standard-library.md"};function c(i,e,l,n,s,h){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="标准库总览" tabindex="-1">标准库总览 <a class="header-anchor" href="#标准库总览" aria-label="Permalink to &quot;标准库总览&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>JavaScript 标准库是 ECMAScript 和 ECMA-402 定义的内置值、构造器、命名空间及方法。它解决对象反射、集合、文本、数值、二进制、时间、国际化、异步组合和资源释放等通用问题，但不包含 DOM、<code>fetch()</code>、<code>console</code>、定时器、<code>structuredClone()</code>、Node.js 文件系统等宿主 API。</p><p>本页负责建立选择地图和快速定位入口，不重复八篇详情的完整签名。语言语义见<a href="/frontend/guide/core/javascript/">JavaScript 语言</a>，具体 API 参数、返回值、异常和示例进入对应详情页。</p><h2 id="_1-阅读边界" tabindex="-1">1. 阅读边界 <a class="header-anchor" href="#_1-阅读边界" aria-label="Permalink to &quot;1. 阅读边界&quot;">​</a></h2><h3 id="_1-1-标准库、语法与宿主-api" tabindex="-1">1.1 标准库、语法与宿主 API <a class="header-anchor" href="#_1-1-标准库、语法与宿主-api" aria-label="Permalink to &quot;1.1 标准库、语法与宿主 API&quot;">​</a></h3><table tabindex="0"><thead><tr><th>能力</th><th>归属</th><th>示例</th></tr></thead><tbody><tr><td>语法与运算规则</td><td>ECMAScript 语言</td><td><code>class</code>、<code>await</code>、解构、<code>typeof</code></td></tr><tr><td>标准内置对象</td><td>ECMAScript 标准库</td><td><code>Array</code>、<code>Map</code>、<code>Promise</code>、<code>JSON</code></td></tr><tr><td>国际化 API</td><td>ECMA-402</td><td><code>Intl.NumberFormat</code>、<code>Intl.Segmenter</code></td></tr><tr><td>浏览器 API</td><td>Web 标准与浏览器宿主</td><td><code>document</code>、<code>fetch</code>、<code>TextEncoder</code></td></tr><tr><td>Node.js API</td><td>Node.js 运行时</td><td><code>process</code>、<code>Buffer</code>、文件系统</td></tr><tr><td>构建工具能力</td><td>Vite、Babel 等</td><td><code>import.meta.env</code>、资源导入</td></tr></tbody></table><p>遇到兼容性问题时，应分别检查语法、内置对象和宿主 API，不能只看“浏览器是否支持 JavaScript”。</p><h3 id="_1-2-调用形式" tabindex="-1">1.2 调用形式 <a class="header-anchor" href="#_1-2-调用形式" aria-label="Permalink to &quot;1.2 调用形式&quot;">​</a></h3><ul><li><strong>构造器</strong>：<code>new Map()</code>、<code>new Date()</code>；</li><li><strong>转换函数</strong>：<code>Number(value)</code>、<code>String(value)</code>，通常不使用 <code>new</code>；</li><li><strong>静态方法</strong>：<code>Array.from()</code>、<code>Object.keys()</code>；</li><li><strong>实例方法</strong>：<code>array.map()</code>、<code>map.get()</code>；</li><li><strong>命名空间函数</strong>：<code>Math.max()</code>、<code>Reflect.get()</code>；</li><li><strong>协议成员</strong>：<code>[Symbol.iterator]()</code>、<code>[Symbol.dispose]()</code>。</li></ul><p>同名 API 可能属于不同对象，例如 <code>Array.prototype.from</code> 不存在，<code>Array.from()</code> 必须由构造器调用。</p><h3 id="_1-3-基础与兼容性敏感能力" tabindex="-1">1.3 基础与兼容性敏感能力 <a class="header-anchor" href="#_1-3-基础与兼容性敏感能力" aria-label="Permalink to &quot;1.3 基础与兼容性敏感能力&quot;">​</a></h3><p>本文把广泛可用的基础 API 与较新能力分开。较新能力即使已进入正式规范，也可能尚未覆盖项目目标运行时，例如：</p><ul><li>Temporal；</li><li>Iterator Helpers 与 Iterator 组合方法；</li><li>显式资源管理；</li><li><code>Promise.try()</code>；</li><li><code>Map.prototype.getOrInsert()</code>；</li><li><code>Math.sumPrecise()</code>；</li><li><code>Uint8Array</code> Base64 / Hex API；</li><li>可伸缩、可转移 ArrayBuffer 的部分成员。</li></ul><p>使用前进行特性检测或通过项目的 Browserslist、运行时版本和兼容性数据确认，不要仅凭规范状态判断可部署性。</p><h2 id="_2-按任务选择" tabindex="-1">2. 按任务选择 <a class="header-anchor" href="#_2-按任务选择" aria-label="Permalink to &quot;2. 按任务选择&quot;">​</a></h2><table tabindex="0"><thead><tr><th>任务</th><th>首选 API</th><th>详情</th></tr></thead><tbody><tr><td>创建、枚举或冻结对象</td><td><code>Object</code></td><td><a href="/frontend/guide/core/javascript/standard-library/fundamentals">基础对象与错误</a></td></tr><tr><td>控制调用接收者或参数</td><td><code>call</code> / <code>apply</code> / <code>bind</code></td><td><a href="/frontend/guide/core/javascript/standard-library/fundamentals">基础对象与错误</a></td></tr><tr><td>唯一属性键或语言协议</td><td><code>Symbol</code></td><td><a href="/frontend/guide/core/javascript/standard-library/fundamentals">基础对象与错误</a></td></tr><tr><td>通用业务列表</td><td><code>Array</code></td><td><a href="/frontend/guide/core/javascript/standard-library/arrays-typed-arrays">数组与 TypedArray</a></td></tr><tr><td>固定类型数值视图</td><td>TypedArray</td><td><a href="/frontend/guide/core/javascript/standard-library/arrays-typed-arrays">数组与 TypedArray</a></td></tr><tr><td>动态键值索引</td><td><code>Map</code></td><td><a href="/frontend/guide/core/javascript/standard-library/maps-sets">Map、Set 与弱引用</a></td></tr><tr><td>唯一值和集合运算</td><td><code>Set</code></td><td><a href="/frontend/guide/core/javascript/standard-library/maps-sets">Map、Set 与弱引用</a></td></tr><tr><td>对象生命周期关联元数据</td><td><code>WeakMap</code></td><td><a href="/frontend/guide/core/javascript/standard-library/maps-sets">Map、Set 与弱引用</a></td></tr><tr><td>文本查找、截取和 Unicode</td><td><code>String</code></td><td><a href="/frontend/guide/core/javascript/standard-library/text-json">字符串、正则与 JSON</a></td></tr><tr><td>模式匹配</td><td><code>RegExp</code></td><td><a href="/frontend/guide/core/javascript/standard-library/text-json">字符串、正则与 JSON</a></td></tr><tr><td>数据交换</td><td><code>JSON</code></td><td><a href="/frontend/guide/core/javascript/standard-library/text-json">字符串、正则与 JSON</a></td></tr><tr><td>浮点数和数学计算</td><td><code>Number</code> / <code>Math</code></td><td><a href="/frontend/guide/core/javascript/standard-library/numbers-math">数值与 Math</a></td></tr><tr><td>任意精度整数</td><td><code>BigInt</code></td><td><a href="/frontend/guide/core/javascript/standard-library/numbers-math">数值与 Math</a></td></tr><tr><td>解析二进制协议</td><td><code>DataView</code></td><td><a href="/frontend/guide/core/javascript/standard-library/binary-data">二进制数据与 Atomics</a></td></tr><tr><td>共享内存同步</td><td><code>SharedArrayBuffer</code> / <code>Atomics</code></td><td><a href="/frontend/guide/core/javascript/standard-library/binary-data">二进制数据与 Atomics</a></td></tr><tr><td>毫秒时间戳和旧 API 互操作</td><td><code>Date</code></td><td><a href="/frontend/guide/core/javascript/standard-library/date-temporal-intl">日期、时间与国际化</a></td></tr><tr><td>时区、日历和本地化</td><td>Temporal / <code>Intl</code></td><td><a href="/frontend/guide/core/javascript/standard-library/date-temporal-intl">日期、时间与国际化</a></td></tr><tr><td>异步结果组合</td><td><code>Promise</code></td><td><a href="/frontend/guide/core/javascript/standard-library/async-iteration-resources">异步迭代与资源管理</a></td></tr><tr><td>惰性序列</td><td>Iterator / Generator</td><td><a href="/frontend/guide/core/javascript/standard-library/async-iteration-resources">异步迭代与资源管理</a></td></tr><tr><td>确定性资源释放</td><td>DisposableStack 等</td><td><a href="/frontend/guide/core/javascript/standard-library/async-iteration-resources">异步迭代与资源管理</a></td></tr></tbody></table><h2 id="_3-基础对象与控制" tabindex="-1">3. 基础对象与控制 <a class="header-anchor" href="#_3-基础对象与控制" aria-label="Permalink to &quot;3. 基础对象与控制&quot;">​</a></h2><h3 id="_3-1-object、function-与-boolean" tabindex="-1">3.1 <code>Object</code>、<code>Function</code> 与 <code>Boolean</code> <a class="header-anchor" href="#_3-1-object、function-与-boolean" aria-label="Permalink to &quot;3.1 `Object`、`Function` 与 `Boolean`&quot;">​</a></h3><ul><li><code>Object</code>：创建、复制、枚举、描述属性、原型操作和完整性控制；</li><li><code>Function</code>：<code>call()</code>、<code>apply()</code>、<code>bind()</code> 以及函数元信息；</li><li><code>Boolean</code>：显式布尔转换和包装对象实例方法。</li></ul><p>对象属性和原型的运行规则见<a href="/frontend/guide/core/javascript/objects-prototypes">对象、原型与类</a>，详情文章只负责标准库 API。</p><h3 id="_3-2-symbol、reflect-与-proxy" tabindex="-1">3.2 <code>Symbol</code>、<code>Reflect</code> 与 <code>Proxy</code> <a class="header-anchor" href="#_3-2-symbol、reflect-与-proxy" aria-label="Permalink to &quot;3.2 `Symbol`、`Reflect` 与 `Proxy`&quot;">​</a></h3><ul><li><code>Symbol()</code> 创建唯一值，<code>Symbol.for()</code> 使用全局注册表；</li><li>well-known Symbol 定义迭代、转换、匹配和释放协议；</li><li><code>Reflect</code> 以函数形式执行对象内部操作；</li><li><code>Proxy</code> 通过 handler trap 拦截这些操作。</li></ul><p>Proxy 不是权限边界，trap 也必须遵守目标对象不变量。</p><h3 id="_3-3-error-家族" tabindex="-1">3.3 Error 家族 <a class="header-anchor" href="#_3-3-error-家族" aria-label="Permalink to &quot;3.3 Error 家族&quot;">​</a></h3><p>基础错误类型包括 <code>Error</code>、<code>TypeError</code>、<code>RangeError</code>、<code>ReferenceError</code>、<code>SyntaxError</code>、<code>URIError</code>、<code>AggregateError</code> 等。<code>cause</code> 保留下层原因；<code>stack</code> 常见但不是 ECMAScript 保证的标准格式。</p><p>错误传播与调试方法见<a href="/frontend/guide/core/javascript/errors-debugging">错误处理与调试</a>。</p><h2 id="_4-集合与文本" tabindex="-1">4. 集合与文本 <a class="header-anchor" href="#_4-集合与文本" aria-label="Permalink to &quot;4. 集合与文本&quot;">​</a></h2><h3 id="_4-1-索引集合" tabindex="-1">4.1 索引集合 <a class="header-anchor" href="#_4-1-索引集合" aria-label="Permalink to &quot;4.1 索引集合&quot;">​</a></h3><p><code>Array</code> 是动态、可含任意值的序列；TypedArray 是对缓冲区的定长数值视图。</p><p>常用 Array API 家族：</p><ul><li>创建：<code>Array.from()</code>、<code>Array.of()</code>、<code>Array.fromAsync()</code>；</li><li>查询：<code>at()</code>、<code>find()</code>、<code>includes()</code>；</li><li>派生：<code>map()</code>、<code>filter()</code>、<code>flatMap()</code>、<code>slice()</code>；</li><li>聚合：<code>reduce()</code>、<code>every()</code>、<code>some()</code>；</li><li>修改：<code>push()</code>、<code>splice()</code>、<code>sort()</code>；</li><li>非修改替代：<code>toSpliced()</code>、<code>toSorted()</code>、<code>toReversed()</code>、<code>with()</code>。</li></ul><h3 id="_4-2-键值集合" tabindex="-1">4.2 键值集合 <a class="header-anchor" href="#_4-2-键值集合" aria-label="Permalink to &quot;4.2 键值集合&quot;">​</a></h3><ul><li><code>Map</code>：任意类型键、动态增删、插入顺序迭代；</li><li><code>Set</code>：唯一值、成员判断、集合运算；</li><li><code>WeakMap</code> / <code>WeakSet</code>：不阻止键或成员被垃圾回收，不可枚举；</li><li><code>WeakRef</code> / <code>FinalizationRegistry</code>：高级弱引用能力，不能承担关键清理。</li></ul><h3 id="_4-3-文本与数据交换" tabindex="-1">4.3 文本与数据交换 <a class="header-anchor" href="#_4-3-文本与数据交换" aria-label="Permalink to &quot;4.3 文本与数据交换&quot;">​</a></h3><ul><li><code>String</code>：UTF-16 文本的访问、查询、转换、规范化和迭代；</li><li><code>RegExp</code>：模式、标志、捕获组、<code>lastIndex</code> 与字符串协议；</li><li><code>JSON</code>：受限数据模型的解析与序列化。</li></ul><p>JSON 不是通用对象克隆协议，不保留原型、Map、Set、BigInt、循环引用或方法。</p><h2 id="_5-数值、二进制与时间" tabindex="-1">5. 数值、二进制与时间 <a class="header-anchor" href="#_5-数值、二进制与时间" aria-label="Permalink to &quot;5. 数值、二进制与时间&quot;">​</a></h2><h3 id="_5-1-number、bigint-与-math" tabindex="-1">5.1 <code>Number</code>、<code>BigInt</code> 与 <code>Math</code> <a class="header-anchor" href="#_5-1-number、bigint-与-math" aria-label="Permalink to &quot;5.1 `Number`、`BigInt` 与 `Math`&quot;">​</a></h3><ul><li><code>Number</code>：IEEE 754 binary64，包含 <code>NaN</code> 和无穷；</li><li><code>BigInt</code>：任意精度整数，不与 Number 直接混合算术；</li><li><code>Math</code>：无状态数学常量和函数。</li></ul><p>货币、数据库 64 位 id 和密码学随机数都有额外边界，不能只选择一个“看起来够大”的数值类型。</p><h3 id="_5-2-缓冲区、视图与共享内存" tabindex="-1">5.2 缓冲区、视图与共享内存 <a class="header-anchor" href="#_5-2-缓冲区、视图与共享内存" aria-label="Permalink to &quot;5.2 缓冲区、视图与共享内存&quot;">​</a></h3><ul><li><code>ArrayBuffer</code> / <code>SharedArrayBuffer</code> 持有字节；</li><li>TypedArray 按固定数值类型解释字节；</li><li><code>DataView</code> 按调用指定字段类型和大小端；</li><li><code>Atomics</code> 在共享整数视图上提供原子操作与等待通知。</li></ul><p>浏览器使用 SharedArrayBuffer 通常需要跨源隔离；这是部署响应头要求，不是构造器调用即可解决。</p><h3 id="_5-3-date、temporal-与-intl" tabindex="-1">5.3 <code>Date</code>、Temporal 与 <code>Intl</code> <a class="header-anchor" href="#_5-3-date、temporal-与-intl" aria-label="Permalink to &quot;5.3 `Date`、Temporal 与 `Intl`&quot;">​</a></h3><p><code>Date</code> 适合与现有毫秒时间戳 API 互操作；Temporal 把瞬间、时区日期时间、无时区日历值和时长拆成不同类型；<code>Intl</code> 负责格式化、排序、复数规则、列表和文本分段。</p><p>存储层保存机器值与时区信息，展示层再本地化，不要存储已经格式化的字符串作为计算来源。</p><h2 id="_6-异步、迭代与资源" tabindex="-1">6. 异步、迭代与资源 <a class="header-anchor" href="#_6-异步、迭代与资源" aria-label="Permalink to &quot;6. 异步、迭代与资源&quot;">​</a></h2><h3 id="_6-1-promise" tabindex="-1">6.1 <code>Promise</code> <a class="header-anchor" href="#_6-1-promise" aria-label="Permalink to &quot;6.1 `Promise`&quot;">​</a></h3><ul><li>实例链：<code>then()</code>、<code>catch()</code>、<code>finally()</code>；</li><li>创建：<code>resolve()</code>、<code>reject()</code>、<code>withResolvers()</code>、<code>try()</code>；</li><li>组合：<code>all()</code>、<code>allSettled()</code>、<code>any()</code>、<code>race()</code>。</li></ul><p>Promise 表示结果，不等于可取消任务；组合方法也不会自动限制并发或取消其他操作。</p><h3 id="_6-2-iterator-与-generator" tabindex="-1">6.2 Iterator 与 Generator <a class="header-anchor" href="#_6-2-iterator-与-generator" aria-label="Permalink to &quot;6.2 Iterator 与 Generator&quot;">​</a></h3><p>Iterator 通过 <code>next()</code> 逐项产生值，Generator 通过 <code>yield</code> 简化 iterator 实现。Iterator Helpers 提供惰性 <code>map()</code>、<code>filter()</code>、<code>take()</code> 等能力，但部署前要确认运行时支持。</p><h3 id="_6-3-显式资源管理" tabindex="-1">6.3 显式资源管理 <a class="header-anchor" href="#_6-3-显式资源管理" aria-label="Permalink to &quot;6.3 显式资源管理&quot;">​</a></h3><p><code>Symbol.dispose</code>、<code>Symbol.asyncDispose</code>、<code>DisposableStack</code>、<code>AsyncDisposableStack</code> 与 <code>using</code> / <code>await using</code> 用结构化作用域表达确定性清理。垃圾回收只管理内存可达性，不能保证外部资源何时关闭。</p><h2 id="_7-全局值与全局函数" tabindex="-1">7. 全局值与全局函数 <a class="header-anchor" href="#_7-全局值与全局函数" aria-label="Permalink to &quot;7. 全局值与全局函数&quot;">​</a></h2><h3 id="_7-1-全局值" tabindex="-1">7.1 全局值 <a class="header-anchor" href="#_7-1-全局值" aria-label="Permalink to &quot;7.1 全局值&quot;">​</a></h3><table tabindex="0"><thead><tr><th>值</th><th>用途</th></tr></thead><tbody><tr><td><code>globalThis</code></td><td>跨宿主访问当前全局对象</td></tr><tr><td><code>Infinity</code></td><td>正无穷数值</td></tr><tr><td><code>NaN</code></td><td>无效数值结果</td></tr><tr><td><code>undefined</code></td><td>未定义原始值</td></tr></tbody></table><p>业务代码不应声明同名局部绑定造成遮蔽。</p><h3 id="_7-2-数值解析" tabindex="-1">7.2 数值解析 <a class="header-anchor" href="#_7-2-数值解析" aria-label="Permalink to &quot;7.2 数值解析&quot;">​</a></h3><ul><li><code>parseInt(string, radix?)</code>；</li><li><code>parseFloat(string)</code>；</li><li><code>isFinite(value)</code>、<code>isNaN(value)</code> 会先隐式转换；</li><li>通常优先 <code>Number.isFinite()</code>、<code>Number.isNaN()</code>。</li></ul><p><code>parseInt()</code> 适合解析字符串前缀，不适合验证“整个输入必须是整数”。</p><h3 id="_7-3-uri-编解码" tabindex="-1">7.3 URI 编解码 <a class="header-anchor" href="#_7-3-uri-编解码" aria-label="Permalink to &quot;7.3 URI 编解码&quot;">​</a></h3><ul><li><code>encodeURI()</code> / <code>decodeURI()</code>：处理完整 URI，保留结构字符；</li><li><code>encodeURIComponent()</code> / <code>decodeURIComponent()</code>：处理单个查询值或路径片段。</li></ul><p>URI 编码不是 HTML 转义或输入校验。已弃用的 <code>escape()</code> / <code>unescape()</code> 不用于新代码。</p><h3 id="_7-4-eval" tabindex="-1">7.4 <code>eval()</code> <a class="header-anchor" href="#_7-4-eval" aria-label="Permalink to &quot;7.4 `eval()`&quot;">​</a></h3><p><code>eval()</code> 动态解析源码，会扩大注入风险，破坏静态分析和优化，并使作用域行为复杂。普通数据解析使用 JSON，规则表达使用明确解释器或配置结构，不把外部文本交给 <code>eval()</code>。</p><h2 id="_8-跨-api-规则" tabindex="-1">8. 跨 API 规则 <a class="header-anchor" href="#_8-跨-api-规则" aria-label="Permalink to &quot;8. 跨 API 规则&quot;">​</a></h2><h3 id="_8-1-相等性不是统一规则" tabindex="-1">8.1 相等性不是统一规则 <a class="header-anchor" href="#_8-1-相等性不是统一规则" aria-label="Permalink to &quot;8.1 相等性不是统一规则&quot;">​</a></h3><table tabindex="0"><thead><tr><th>位置</th><th>规则</th></tr></thead><tbody><tr><td><code>===</code>、<code>indexOf()</code></td><td>Strict Equality</td></tr><tr><td><code>Object.is()</code></td><td>SameValue</td></tr><tr><td><code>includes()</code>、Map 键、Set 值</td><td>SameValueZero</td></tr><tr><td>对象内容比较</td><td>标准库没有通用深相等</td></tr></tbody></table><h3 id="_8-2-复制通常是浅复制" tabindex="-1">8.2 复制通常是浅复制 <a class="header-anchor" href="#_8-2-复制通常是浅复制" aria-label="Permalink to &quot;8.2 复制通常是浅复制&quot;">​</a></h3><p>对象展开、<code>Object.assign()</code>、<code>Array.prototype.slice()</code>、<code>Array.from()</code> 等不会递归复制嵌套对象。<code>structuredClone()</code> 能处理更多对象图，但属于宿主 API。</p><h3 id="_8-3-回调参数由-api-决定" tabindex="-1">8.3 回调参数由 API 决定 <a class="header-anchor" href="#_8-3-回调参数由-api-决定" aria-label="Permalink to &quot;8.3 回调参数由 API 决定&quot;">​</a></h3><p>数组回调常收到 <code>(value, index, array)</code>，Map / Set 的 <code>forEach</code> 参数顺序不同，Promise 回调只收到完成值或拒绝原因。不要把签名不同的函数直接互换，例如 <code>array.map(parseInt)</code>。</p><h3 id="_8-4-修改与派生必须区分" tabindex="-1">8.4 修改与派生必须区分 <a class="header-anchor" href="#_8-4-修改与派生必须区分" aria-label="Permalink to &quot;8.4 修改与派生必须区分&quot;">​</a></h3><p><code>sort()</code>、<code>reverse()</code>、<code>splice()</code> 修改原数组；<code>toSorted()</code>、<code>toReversed()</code>、<code>toSpliced()</code> 返回新数组。API 名称相近不代表状态语义相同。</p><h2 id="_9-学习顺序" tabindex="-1">9. 学习顺序 <a class="header-anchor" href="#_9-学习顺序" aria-label="Permalink to &quot;9. 学习顺序&quot;">​</a></h2><ol><li>先学 <code>Object</code>、<code>Array</code>、<code>String</code>、<code>Number</code> 与 Error；</li><li>再学 Map / Set、JSON、Promise 与 <code>Intl</code>；</li><li>有二进制或高性能数据需求时学习 TypedArray、ArrayBuffer 与 DataView；</li><li>有惰性序列时学习 Iterator / Generator；</li><li>有时区和日历计算时评估 Temporal；</li><li>只有确定性清理和共享内存需求明确时，再进入资源管理与 Atomics。</li></ol><h2 id="_10-参考资料" tabindex="-1">10. 参考资料 <a class="header-anchor" href="#_10-参考资料" aria-label="Permalink to &quot;10. 参考资料&quot;">​</a></h2><ul><li><a href="https://tc39.es/ecma262/" target="_blank" rel="noreferrer">ECMAScript Language Specification</a></li><li><a href="https://tc39.es/ecma402/" target="_blank" rel="noreferrer">ECMAScript Internationalization API Specification</a></li><li><a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects" target="_blank" rel="noreferrer">MDN：Standard built-in objects</a></li><li><a href="https://github.com/tc39/proposals" target="_blank" rel="noreferrer">TC39 proposals</a></li></ul>',80)])])}const b=d(r,[["render",c]]);export{u as __pageData,b as default};
